// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 funding, uint256 v) public {
        // admissible domain: the contract is funded with a positive, bounded amount;
        // the requested withdrawal differs from that amount so "gain == v" is checkable
        vm.assume(funding > 0 && funding < 1e30);
        vm.assume(v != funding);

        // fund c through its payable receive()
        vm.deal(address(this), 1e30);
        (bool funded, ) = address(c).call{value: funding}("");
        require(funded, "funding failed");

        uint256 callerBefore = address(this).balance;

        bool ok;
        try c.withdraw(v) { ok = true; } catch { ok = false; }

        // RULE: a withdrawal either reverts, or pays out exactly the requested _value
        // (reference: transfer(v) reverts if balance < v, else moves exactly v;
        //  mutant: always moves address(c).balance, which != v for every admissible input)
        assertTrue(!ok || address(this).balance == callerBefore + v);
    }
}
